            if json {
                let json_string =
                    serde_json::to_string(&projects).expect("failed to serialize projects to JSON");
                writeln!(handle, "{json_string}").expect("failed to print");
            } else {
                projects
                    .iter()
                    .for_each(|project| writeln!(handle, "{project}").expect("failed to print"));
