                    }

                    Entity::Workspace { json: entity_json } => {
                        let json = json_flag || entity_json;
                        let workspaces = entities
                            .workspaces
                            .iter()
                            .take(count.unwrap_or(usize::MAX))
                            .collect::<Vec<_>>();

                        if json {
                            let json_string = serde_json::to_string(&workspaces)
