use crate::api::client::ApiClient;
use crate::constants::NO_PROJECT;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

pub struct BillCommand;

impl BillCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = aggregate_billable_time(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let mut projects: Vec<_> = totals.into_iter().collect();
        projects.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
            right_seconds
                .cmp(left_seconds)
                .then_with(|| left_name.cmp(right_name))
        });

        let total: i64 = projects.iter().map(|(_, seconds)| seconds).sum();
        for (project, seconds) in projects {
            println!("{seconds}s  {project}");
        }
        println!("{total}s  Total");
        Ok(())
    }
}

fn aggregate_billable_time(entries: &[TimeEntry]) -> HashMap<String, i64> {
    entries
        .iter()
        .filter(|entry| entry.billable && entry.stop.is_some())
        .map(|entry| {
            let rounded = round_up_to_billing_unit(entry.duration);
            let project = entry
                .project
                .as_ref()
                .map(|project| project.name.clone())
                .unwrap_or_else(|| NO_PROJECT.to_string());
            (project, rounded)
        })
        .fold(HashMap::new(), |mut totals, (project, seconds)| {
            *totals.entry(project).or_default() += seconds;
            totals
        })
}

fn round_up_to_billing_unit(seconds: i64) -> i64 {
    if seconds <= 0 {
        return 0;
    }
    ((seconds + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::{Project, TimeEntry};
    use chrono::{TimeZone, Utc};

    fn entry(
        id: i64,
        duration: i64,
        billable: bool,
        stop: bool,
        project: Option<&str>,
    ) -> TimeEntry {
        let start = Utc.timestamp_opt(1_700_000_000 + id, 0).single().unwrap();
        TimeEntry {
            id,
            description: String::new(),
            start,
            stop: stop.then_some(start),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: project.map(|name| Project {
                id,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: start,
                created_at: start,
                color: String::new(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn rounds_each_entry_before_aggregating_and_sorts() {
        let totals = aggregate_billable_time(&[
            entry(1, 7 * 60, true, true, Some("Beta")),
            entry(2, 22 * 60, true, true, Some("Beta")),
            entry(3, 15 * 60 + 1, true, true, Some("Alpha")),
            entry(4, 60 * 60, true, true, None),
            entry(5, 60 * 60, false, true, Some("Ignored")),
            entry(6, 60 * 60, true, false, Some("Running")),
        ]);

        assert_eq!(totals["Beta"], 45 * 60);
        assert_eq!(totals["Alpha"], 30 * 60);
        assert_eq!(totals[NO_PROJECT], 60 * 60);
        assert!(!totals.contains_key("Ignored"));
        assert!(!totals.contains_key("Running"));
    }

    #[test]
    fn rounds_zero_and_positive_durations() {
        assert_eq!(round_up_to_billing_unit(0), 0);
        assert_eq!(round_up_to_billing_unit(1), 15 * 60);
        assert_eq!(round_up_to_billing_unit(15 * 60), 15 * 60);
        assert_eq!(round_up_to_billing_unit(15 * 60 + 1), 30 * 60);
    }
}

